INSERT INTO `assets_meta` VALUES (1,'app','/','481aa244-1ba4-4522-8ac6-093a927b3526.jpg','481aa244-1ba4-4522-8ac6-093a927b3526','jpg','481aa244-1ba4-4522-8ac6-093a927b3526.jpg','{\"data\": [], \"size\": 156313, \"width\": 1200, \"height\": 1200, \"duration\": null, \"mime_type\": \"image/jpeg\", \"last_modified\": 1722418240}','2024-07-31 09:30:40','2024-07-31 09:30:40'),(2,'app','event_types','image4.jpg','image4','jpg','event_types/image4.jpg','{\"data\": [], \"size\": 106379, \"width\": 276, \"height\": 196, \"duration\": null, \"mime_type\": \"image/jpeg\", \"last_modified\": 1722418305}','2024-07-31 09:31:45','2024-07-31 09:31:45'),(3,'app','event_types','image3.jpg','image3','jpg','event_types/image3.jpg','{\"data\": [], \"size\": 76274, \"width\": 274, \"height\": 196, \"duration\": null, \"mime_type\": \"image/jpeg\", \"last_modified\": 1722418309}','2024-07-31 09:31:49','2024-07-31 09:31:49'),(4,'app','event_types','image2.jpg','image2','jpg','event_types/image2.jpg','{\"data\": [], \"size\": 59842, \"width\": 274, \"height\": 196, \"duration\": null, \"mime_type\": \"image/jpeg\", \"last_modified\": 1722418310}','2024-07-31 09:31:50','2024-07-31 09:31:50'),(5,'app','event_types','image1.jpg','image1','jpg','event_types/image1.jpg','{\"data\": [], \"size\": 382196, \"width\": 556, \"height\": 384, \"duration\": null, \"mime_type\": \"image/jpeg\", \"last_modified\": 1722418312}','2024-07-31 09:31:52','2024-07-31 09:31:52'),(6,'app','/','481aa244-1ba4-4522-8ac6-093a927b3526-1722549137.jpg','481aa244-1ba4-4522-8ac6-093a927b3526-1722549137','jpg','481aa244-1ba4-4522-8ac6-093a927b3526-1722549137.jpg','{\"data\": [], \"size\": 156313, \"width\": 1200, \"height\": 1200, \"duration\": null, \"mime_type\": \"image/jpeg\", \"last_modified\": 1722549138}','2024-08-01 21:52:18','2024-08-01 21:52:18'),(7,'app','/','481aa244-1ba4-4522-8ac6-093a927b3526-1722549214.jpg','481aa244-1ba4-4522-8ac6-093a927b3526-1722549214','jpg','481aa244-1ba4-4522-8ac6-093a927b3526-172254921